{"code":"const { readFile } = await import('node:fs/promises');
const app = await tools.cua({ method: 'getApp', params: { selector: 'test.fixture' } });
const target = { appHandle: app.appHandle, windowId: '7' };
const first = await tools.cua({ method: 'getState', params: { ...target, maxElements: 1 } });
const state = first.truncated ? await tools.cua({ method: 'getState', params: { ...target, maxElements: 16 } }) : first;
const shot = await tools.cua({ method: 'screenshot', params: { appHandle: app.appHandle, windowId: '7' } });
const bytes = await readFile(shot.path);
inspect({ appHandle: app.appHandle, initiallyTruncated: first.truncated, recoveredTextField: !first.tree.includes('AXTextField') && state.tree.includes('AXTextField'), hasIncrement: state.tree.includes('Increment'), pngBytes: bytes.length, signature: bytes.subarray(0, 8).toString('hex'), imageWidth: shot.width, imageHeight: shot.height }, shot); return;","description":"Read native CUA values and receive one screenshot"}

