{"code":"const { readFile, writeFile, unlink } = await import('node:fs/promises');
const { resolve } = await import('node:path');
const { pathToFileURL } = await import('node:url');
const { connectCua } = await import(pathToFileURL(resolve('cua-bridge.mjs')).href);
await writeFile('fixture-ax-failure', '');
try {
  const cua = connectCua(() => tools.cua);
  const app = await cua.getApp('test.fixture');
  const windows = await app.getWindows();
  const window = await app.getWindow(windows[0].windowId);
  const failures = [];
  for (const surface of [app, window]) {
    try { await surface.getAccessibilityTree(); throw new Error('Expected AX failure'); }
    catch (error) { if (!error.message.includes('Fixture accessibility read failed')) throw error; failures.push(error.message); }
  }
  let coordinateRefused = false;
  try { await window.click([100, 100], { relative: true }); }
  catch (error) { if (!error.message.includes('Window has no observation')) throw error; coordinateRefused = true; }
  if (!coordinateRefused) throw new Error('Coordinate input accepted without observation');
  const shot = await window.getScreenshot();
  const coordinateDispatched = (await window.click([100, 100], { relative: true })).dispatched;
  let elementRefused = false;
  try { await window.invoke('0'); }
  catch (error) { if (!error.message.includes('Read getAccessibilityTree')) throw error; elementRefused = true; }
  if (!elementRefused) throw new Error('Element input accepted without an AX snapshot');
  inspect({ axFailures: failures.length, screenshotWindow: window.windowId, pngBytes: (await readFile(shot.path)).byteLength, elementRefused, coordinateRefused, coordinateDispatched }, shot);
} finally { await unlink('fixture-ax-failure'); }","description":"Capture through the object API despite application and window AX failures"}

