{"code":"const { writeFile, unlink } = await import('node:fs/promises');
const { resolve } = await import('node:path');
const { pathToFileURL } = await import('node:url');
const { connectCua } = await import(pathToFileURL(resolve('cua-bridge.mjs')).href);
const cua = connectCua(() => tools.cua);
const app = await cua.getApp('test.fixture');
const results = [];
for (const attribute of ['AXValue', 'AXSelectedTextRange']) {
  await writeFile('fixture-ax-writability-failure', attribute);
  try {
    const tree = await app.getAccessibilityTree();
    const field = attribute === 'AXValue' ? 'valueWritable' : 'selectionWritable';
    if (!tree.includes(field + '=unknown') || tree.includes(field + '=true')) throw new Error('Unknown writability was lost');
    if (!tree.includes('Increment') || !tree.includes('Count:')) throw new Error('Other nodes were lost');
    let writeRefused = false;
    try {
      if (attribute === 'AXValue') await app.setValue('1', 'must not be written');
      else await app.selectText('1', 'Fixture');
    } catch (error) {
      if (!error.message.includes('writability of ' + attribute + ' failed with error -25200')) throw error;
      writeRefused = true;
    }
    if (!writeRefused) throw new Error('Write accepted with unknown writability');
    results.push({ attribute, unknown: true, otherNodesRetained: true, writeRefused });
  } finally { await unlink('fixture-ax-writability-failure'); }
}
inspect(results);","description":"Retain AX trees with unknown writability and reject writes"}

